import java.io.*;
import java.util.*;

// Stand-in for the given Main.class (rebuilt with javap -c): nextDouble()/nextInt() each followed by nextLine()
class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String lastname = "";
        System.out.print("Enter name: ");
        String name = sc.nextLine();
        System.out.print("Enter gpa: ");
        double gpa = sc.nextDouble();
        sc.nextLine();
        System.out.println("1. Test setName()");
        System.out.println("2. Test getPass()");
        System.out.print("Enter TC (1 or 2): ");
        int tc = sc.nextInt();
        sc.nextLine();
        Student st = new Student(name, gpa);
        if (tc == 1) {
            System.out.print("Enter lastname: ");
            lastname = sc.nextLine();
        }
        System.out.println("OUTPUT:");
        switch (tc) {
            case 1:
                st.setName(lastname);
                System.out.printf("%s\r\n", st.toString());          // \r\n: the given Main prints Windows line ends
                break;
            case 2:
                System.out.println(st.getPass());
                break;
        }
        System.out.println();
    }
}
